   170	    /// Record what a progress event names: each file copied (or, on a
   171	    /// source, sent), failed or deleted, and the phase changes.
   172	    pub(crate) async fn observe(&self, event: &ProgressEvent) {
   173	        let (sender, bodies) = {
   174	            let mut state = self.state();
   175	            let Some(active) = state.active.as_mut() else {
   176	                return;
   177	            };
   178	            let bodies = match event {
   179	                ProgressEvent::FileComplete { path } => vec![match active.role {
   180	                    Role::Source => EventBody::FileSent { path: path.clone() },
   181	                    _ => EventBody::FileCopied {
   182	                        path: path.clone(),
   183	                        bytes: None,
   184	                    },
   185	                }],
   186	                ProgressEvent::FileFailed { path, reason } => {
   187	                    active.failed.insert(path.clone());
   188	                    vec![EventBody::FileFailed {
   189	                        path: path.clone(),
   190	                        reason: reason.clone(),
   191	                    }]
   192	                }
   193	                ProgressEvent::Deleted { path } => {
   194	                    vec![EventBody::FileDeleted { path: path.clone() }]
   195	                }
   196	                ProgressEvent::ManifestBatch { files, bytes } => {
   197	                    active.planned_files = active.planned_files.saturating_add(*files as u64);
   198	                    active.planned_bytes = active.planned_bytes.saturating_add(*bytes);
   199	                    vec![]
   200	                }
   201	                ProgressEvent::DiffComplete => vec![EventBody::Diagnostic {
   202	                    message: format!(
   203	                        "compared the whole source list: {} file(s), {} to send",
   204	                        active.planned_files,
   205	                        format_bytes(active.planned_bytes)
   206	                    ),
   207	                }],
   208	                ProgressEvent::DeleteBegin => {
   209	                    active.deleting = true;
   210	                    vec![
   211	                        EventBody::Phase {
   212	                            name: "transfer".into(),
   213	                            state: PhaseState::End,
   214	                        },
   215	                        EventBody::Phase {
   216	                            name: "delete".into(),
   217	                            state: PhaseState::Start,
   218	                        },
   219	                    ]
   220	                }
   221	                _ => vec![],
   222	            };
   223	            (active.sender.clone(), bodies)
   224	        };
   225	        for body in bodies {
   226	            sender.record_async(body).await;
   227	        }
   228	    }
