   253	    /// Close the log: name the failed files the summary lists that were not
   254	    /// seen live, end the open phase, record the diagnostics and the
   255	    /// summary, then `run-end`, and finish the file.
   256	    pub(crate) async fn close(
   257	        &self,
   258	        outcome: Outcome,
   259	        detail: Option<String>,
   260	        summary: Option<TransferSummary>,
   261	    ) {
   262	        let (active, notes, summary, error, run_id) = {
   263	            let mut state = self.state();
   264	            let Some(active) = state.active.take() else {
   265	                return;
   266	            };
   267	            (
   268	                active,
   269	                std::mem::take(&mut state.notes),
   270	                summary.or_else(|| state.summary.take()),
   271	                state.error.take(),
   272	                state.run_id.clone(),
   273	            )
   274	        };
   275	        // The open phase ends first: what the summary adds below was learned
   276	        // at the end, while every failure seen live sits inside the phase.
   277	        let mut bodies = vec![EventBody::Phase {
   278	            name: if active.deleting {
   279	                "delete"
   280	            } else {
   281	                "transfer"
   282	            }
   283	            .into(),
   284	            state: PhaseState::End,
   285	        }];
   286	        if let Some(summary) = &summary {
   287	            for path in &summary.failed_paths {
   288	                if active.failed.contains(path) {
   289	                    continue;
   290	                }
   291	                let reason = summary
   292	                    .failures
   293	                    .iter()
   294	                    .find(|failure| &failure.relative_path == path)
   295	                    .map_or(NO_REASON_REPORTED, |failure| failure.reason.as_str());
   296	                bodies.push(EventBody::FileFailed {
   297	                    path: path.clone(),
   298	                    reason: reason.to_string(),
   299	                });
   300	            }
   301	            if summary.failed_paths_truncated {
   302	                bodies.push(EventBody::Diagnostic {
   303	                    message: format!(
   304	                        "the list of failed files was cut short for size; {} failed in all",
   305	                        summary.files_failed
   306	                    ),
   307	                });
   308	            }
   309	        }
   310	        let elapsed = active.started.elapsed();
   311	        if active.planned_files > 0 {
   312	            bodies.push(EventBody::Diagnostic {
   313	                message: format!(
   314	                    "planned: {} file(s), {}",
   315	                    active.planned_files,
   316	                    format_bytes(active.planned_bytes)
   317	                ),
   318	            });
   319	        }
   320	        for message in notes {
   321	            bodies.push(EventBody::Diagnostic { message });
   322	        }
   323	        if let Some(summary) = &summary {
   324	            bodies.push(EventBody::Diagnostic {
   325	                message: if summary.in_stream_carrier_used {
   326	                    "payload carrier: in-stream (gRPC)".into()
   327	                } else {
   328	                    "payload carrier: TCP data plane".into()
   329	                },
   330	            });
   331	            if summary.files_resumed > 0 {
   332	                bodies.push(EventBody::Diagnostic {
   333	                    message: format!("resumed: {} file(s)", summary.files_resumed),
   334	                });
   335	            }
   336	            let seconds = elapsed.as_secs_f64();
   337	            if seconds > 0.0 && summary.bytes_transferred > 0 {
   338	                bodies.push(EventBody::Diagnostic {
   339	                    message: format!(
   340	                        "average: {}/s over the whole job",
   341	                        format_bytes((summary.bytes_transferred as f64 / seconds) as u64)
   342	                    ),
   343	                });
   344	            }
   345	            bodies.push(EventBody::Summary(Summary {
   346	                files_copied: summary.files_transferred,
   347	                files_deleted: summary.entries_deleted,
   348	                files_failed: summary.files_failed,
   349	                bytes_copied: summary.bytes_transferred,
   350	                elapsed_ms: u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX),
   351	            }));
   352	        }
   353	        for body in bodies {
   354	            active.sender.record_async(body).await;
   355	        }
   356	        let detail = error.or(detail);
   357	        let writer = active.writer;
   358	        match tokio::task::spawn_blocking(move || writer.finish(outcome, detail)).await {
   359	            Ok(report) if !report.complete => log::warn!(
   360	                "job {run_id}: its log is incomplete: {}",
   361	                report.problem.unwrap_or_default()
   362	            ),
   363	            Ok(_) => {}
   364	            Err(error) => log::warn!("job {run_id}: closing its log failed: {error}"),
   365	        }
   366	    }
   367	}
