   457	pub(crate) type JobLogStream = ReceiverStream<Result<JobLogChunk, Status>>;
   458	
   459	/// `GetJobLog`: every log this daemon kept for the job (in one role, when
   460	/// asked), each as a header and then its bytes as stored.
   461	pub(crate) async fn serve(
   462	    logs: Option<&JobLogs>,
   463	    request: GetJobLogRequest,
   464	) -> Result<Response<JobLogStream>, Status> {
   465	    let id = request.transfer_id;
   466	    if !job_log::valid_id(&id) {
   467	        return Err(Status::invalid_argument(format!("{id:?} is not a job ID")));
   468	    }
   469	    let role = if request.role.is_empty() {
   470	        None
   471	    } else {
   472	        Some(
   473	            request
   474	                .role
   475	                .parse::<Role>()
   476	                .map_err(|error| Status::invalid_argument(format!("{error:#}")))?,
   477	        )
   478	    };
   479	    let Some(logs) = logs else {
   480	        return Err(Status::not_found("this daemon keeps no job logs"));
   481	    };
   482	    let dir = logs.dir.clone();
   483	    let found = {
   484	        let dir = dir.clone();
   485	        let id = id.clone();
   486	        tokio::task::spawn_blocking(move || job_log::logs_for_run(&dir, &id, role))
   487	            .await
   488	            .map_err(|error| Status::internal(format!("listing job logs: {error}")))?
   489	            .map_err(|error| Status::internal(format!("listing job logs: {error:#}")))?
   490	    };
   491	    if found.is_empty() {
   492	        return Err(Status::not_found(match role {
   493	            Some(role) => format!("no {} log for job {id}", role.as_str()),
   494	            None => format!("no log for job {id}"),
   495	        }));
   496	    }
   497	    let (tx, rx) = mpsc::channel(8);
   498	    tokio::spawn(async move {
   499	        for log in found {
   500	            match send_log(&dir, log, &tx).await {
   501	                Ok(true) => {}
   502	                // The caller hung up.
   503	                Ok(false) => return,
   504	                Err(status) => {
   505	                    let _ = tx.send(Err(status)).await;
   506	                    return;
   507	                }
   508	            }
   509	        }
   510	    });
   511	    Ok(Response::new(ReceiverStream::new(rx)))
   512	}
   513	
   514	/// Send one log; `Ok(false)` when the caller has gone.
   515	async fn send_log(
   516	    dir: &Path,
   517	    log: FoundLog,
   518	    tx: &mpsc::Sender<Result<JobLogChunk, Status>>,
   519	) -> Result<bool, Status> {
   520	    let unreadable =
   521	        |error: std::io::Error| Status::internal(format!("reading a job log: {error}"));
   522	    let (mut file, finished) = match tokio::fs::File::open(&log.path).await {
   523	        Ok(file) => (file, log.finished),
   524	        // The run finished between listing and opening: its partial is gone
   525	        // and its finished log is in place.
   526	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
   527	            let dir = dir.to_path_buf();
   528	            let key = log.key.clone();
   529	            let Some(now) = tokio::task::spawn_blocking(move || job_log::find_log(&dir, &key))
   530	                .await
   531	                .map_err(|error| Status::internal(format!("finding a job log: {error}")))?
   532	            else {
   533	                return Ok(true);
   534	            };
   535	            (
   536	                tokio::fs::File::open(&now.path).await.map_err(unreadable)?,
   537	                now.finished,
   538	            )
   539	        }
   540	        Err(error) => return Err(unreadable(error)),
   541	    };
   542	    let header = JobLogHeader {
   543	        role: log.key.role().as_str().into(),
   544	        participant: log.key.participant().into(),
   545	        attempt: log.key.attempt(),
   546	        finished,
   547	    };
   548	    let chunk = |payload| {
   549	        Ok(JobLogChunk {
   550	            payload: Some(payload),
   551	        })
   552	    };
   553	    if tx
   554	        .send(chunk(job_log_chunk::Payload::Header(header)))
   555	        .await
   556	        .is_err()
   557	    {
   558	        return Ok(false);
   559	    }
   560	    let mut buf = vec![0u8; CHUNK_BYTES];
   561	    loop {
   562	        let read = file.read(&mut buf).await.map_err(unreadable)?;
   563	        if read == 0 {
   564	            return Ok(true);
   565	        }
   566	        if tx
   567	            .send(chunk(job_log_chunk::Payload::Data(buf[..read].to_vec())))
   568	            .await
   569	            .is_err()
   570	        {
   571	            return Ok(false);
   572	        }
   573	    }
   574	}
