 36	impl JobLogs {
 37	    /// The logs under `state_dir`, kept to the newest `keep`, under this
 38	    /// machine's ID (made on first use). First finishes every log a stopped
 39	    /// daemon left behind. Blocking: call it before serving.
 40	    pub(crate) fn open(state_dir: &Path, keep: usize) -> std::io::Result<Self> {
 41	        let participant = job_log::machine_id(state_dir)?;
 42	        let dir = state_dir.join("jobs").join("logs");
 43	        let recovery = job_log::recover(&dir);
 44	        if !recovery.finished.is_empty() {
 45	            eprintln!(
 46	                "blitd: finished {} job log(s) left by an earlier run as interrupted",
 47	                recovery.finished.len()
 48	            );
 49	        }
 50	        for problem in &recovery.problems {
 51	            log::warn!("job log recovery: {problem}");
 52	        }
 53	        Ok(Self {
 54	            dir,
 55	            participant,
 56	            keep,
 57	        })
 58	    }
