 65	    /// Start the log of job `run_id` in `role`. `None`, with a warning, only
 66	    /// when the ID cannot name a log; a log never stops a job.
 67	    pub(crate) fn start(&self, run_id: &str, role: Role, run: RunInfo) -> Option<LogWriter> {
 68	        match LogKey::new(run_id, self.participant.clone(), role, 1) {
 69	            Ok(key) => Some(LogWriter::start(&self.dir, key, run, self.keep)),
 70	            Err(error) => {
 71	                log::warn!("job {run_id}: not logged: {error:#}");
 72	                None
 73	            }
 74	        }
 75	    }
