 78	/// What `TransferSummary.failed_paths` names but a file's own failure was
 79	/// never seen live gets this reason when the summary's capped list kept
 80	/// none.
 81	const NO_REASON_REPORTED: &str = "failed (the transfer's report kept no reason)";
 82	
 83	/// One job's log as the daemon's parts see it. Made when the job
 84	/// registers and owned by the job's dispatcher task, which outlives the
 85	/// raced session future; started once the job's role is known (a served
 86	/// session learns it at open); fed from the progress relays; closed by the
 87	/// dispatcher after the race settles. Cheap to clone.
 88	#[derive(Clone)]
 89	pub(crate) struct JobLog {
 90	    inner: Arc<Mutex<LogState>>,
 91	}
 92	
 93	struct LogState {
 94	    logs: Option<JobLogs>,
 95	    run_id: String,
 96	    active: Option<ActiveLog>,
 97	    /// Diagnostics to record at close.
 98	    notes: Vec<String>,
 99	    summary: Option<TransferSummary>,
100	    /// The job's own failure message, when the dispatcher only has a
101	    /// marker (a delegated pull's phased error).
102	    error: Option<String>,
103	}
104	
105	struct ActiveLog {
106	    writer: LogWriter,
107	    sender: LogSender,
108	    role: Role,
109	    started: Instant,
110	    planned_files: u64,
111	    planned_bytes: u64,
112	    deleting: bool,
113	    /// Failed files already named, so the summary's list adds only the
114	    /// rest.
115	    failed: HashSet<String>,
116	}
117	
118	impl JobLog {
119	    pub(crate) fn new(logs: Option<JobLogs>, run_id: &str) -> Self {
120	        Self {
121	            inner: Arc::new(Mutex::new(LogState {
122	                logs,
123	                run_id: run_id.to_string(),
124	                active: None,
125	                notes: Vec::new(),
126	                summary: None,
127	                error: None,
128	            })),
129	        }
130	    }
131	
132	    fn state(&self) -> std::sync::MutexGuard<'_, LogState> {
133	        self.inner
134	            .lock()
135	            .unwrap_or_else(|poisoned| poisoned.into_inner())
136	    }
137	
138	    /// Start the log in `role`; once only, and only when the daemon keeps
139	    /// logs. Safe from sync code inside a runtime: the only event it
140	    /// records goes into a fresh, empty queue, so it never waits.
141	    pub(crate) fn start(&self, role: Role, run: RunInfo) {
142	        let mut state = self.state();
143	        if state.active.is_some() {
144	            return;
145	        }
146	        let Some(writer) = state
147	            .logs
148	            .as_ref()
149	            .and_then(|logs| logs.start(&state.run_id, role, run))
150	        else {
151	            return;
152	        };
153	        let sender = writer.sender();
154	        sender.record(EventBody::Phase {
155	            name: "transfer".into(),
156	            state: PhaseState::Start,
157	        });
158	        state.active = Some(ActiveLog {
159	            writer,
160	            sender,
161	            role,
162	            started: Instant::now(),
163	            planned_files: 0,
164	            planned_bytes: 0,
165	            deleting: false,
166	            failed: HashSet::new(),
167	        });
168	    }
169	
170	    /// Record what a progress event names: each file copied (or, on a
171	    /// source, sent), failed or deleted, and the phase changes.
172	    pub(crate) async fn observe(&self, event: &ProgressEvent) {
173	        let (sender, bodies) = {
174	            let mut state = self.state();
175	            let Some(active) = state.active.as_mut() else {
176	                return;
177	            };
178	            let bodies = match event {
179	                ProgressEvent::FileComplete { path } => vec![match active.role {
180	                    Role::Source => EventBody::FileSent { path: path.clone() },
181	                    _ => EventBody::FileCopied {
182	                        path: path.clone(),
183	                        bytes: None,
184	                    },
185	                }],
186	                ProgressEvent::FileFailed { path, reason } => {
187	                    active.failed.insert(path.clone());
188	                    vec![EventBody::FileFailed {
189	                        path: path.clone(),
190	                        reason: reason.clone(),
191	                    }]
192	                }
193	                ProgressEvent::Deleted { path } => {
194	                    vec![EventBody::FileDeleted { path: path.clone() }]
195	                }
196	                ProgressEvent::ManifestBatch { files, bytes } => {
197	                    active.planned_files = active.planned_files.saturating_add(*files as u64);
198	                    active.planned_bytes = active.planned_bytes.saturating_add(*bytes);
199	                    vec![]
200	                }
201	                ProgressEvent::DiffComplete => vec![EventBody::Diagnostic {
202	                    message: format!(
203	                        "compared the whole source list: {} file(s), {} to send",
204	                        active.planned_files,
205	                        format_bytes(active.planned_bytes)
206	                    ),
207	                }],
208	                ProgressEvent::DeleteBegin => {
209	                    active.deleting = true;
210	                    vec![
211	                        EventBody::Phase {
212	                            name: "transfer".into(),
213	                            state: PhaseState::End,
214	                        },
215	                        EventBody::Phase {
216	                            name: "delete".into(),
217	                            state: PhaseState::Start,
218	                        },
219	                    ]
220	                }
221	                _ => vec![],
222	            };
223	            (active.sender.clone(), bodies)
224	        };
225	        for body in bodies {
226	            sender.record_async(body).await;
227	        }
228	    }
229	
230	    /// A diagnostic line for the log, recorded at close.
231	    pub(crate) fn note(&self, line: String) {
232	        self.state().notes.push(line);
233	    }
