240	    /// How many files failed on their own, by the noted summary.
241	    pub(crate) fn noted_files_failed(&self) -> u64 {
242	        self.state()
243	            .summary
244	            .as_ref()
245	            .map_or(0, |summary| summary.files_failed)
246	    }
