369	/// How a job ended, for its log: `ok` and `error` as the dispatcher scored
370	/// them, whether its `CancelJob` token fired, and how many files failed on
371	/// their own.
372	pub(crate) fn job_outcome(
373	    ok: bool,
374	    error: Option<&str>,
375	    cancelled: bool,
376	    files_failed: u64,
377	) -> (Outcome, Option<String>) {
378	    if ok {
379	        return if files_failed > 0 {
380	            (
381	                Outcome::Failed,
382	                Some(format!("{files_failed} file(s) failed")),
383	            )
384	        } else {
385	            (Outcome::Ok, None)
386	        };
387	    }
388	    if cancelled {
389	        return (Outcome::Cancelled, Some("cancelled via CancelJob".into()));
390	    }
391	    if error == Some(CLIENT_HUNG_UP) {
392	        return (
393	            Outcome::Cancelled,
394	            Some("the client hung up before the job finished".into()),
395	        );
396	    }
397	    (Outcome::Failed, error.map(str::to_string))
398	}
