403	/// The transfer options a log's `run-start` lists, in words.
404	pub(crate) fn option_words(
405	    compare_mode: ComparisonMode,
406	    mirror: Option<MirrorMode>,
407	    filter: Option<&FilterSpec>,
408	    resume: Option<&ResumeSettings>,
409	    ignore_existing: bool,
410	    require_complete_scan: bool,
411	) -> Vec<String> {
412	    let word = |name: &str, prefix: &str| {
413	        name.trim_start_matches(prefix)
414	            .to_lowercase()
415	            .replace('_', "-")
416	    };
417	    let mut words = Vec::new();
418	    if !matches!(
419	        compare_mode,
420	        ComparisonMode::Unspecified | ComparisonMode::SizeMtime
421	    ) {
422	        words.push(format!(
423	            "compare={}",
424	            word(compare_mode.as_str_name(), "COMPARISON_MODE_")
425	        ));
426	    }
427	    if let Some(mirror) =
428	        mirror.filter(|mirror| !matches!(mirror, MirrorMode::Unspecified | MirrorMode::Off))
429	    {
430	        words.push(format!(
431	            "mirror={}",
432	            word(mirror.as_str_name(), "MIRROR_MODE_")
433	        ));
434	    }
435	    if let Some(filter) = filter {
436	        words.extend(filter.include.iter().map(|glob| format!("include={glob}")));
437	        words.extend(filter.exclude.iter().map(|glob| format!("exclude={glob}")));
438	        if let Some(min) = filter.min_size {
439	            words.push(format!("min-size={min}"));
440	        }
441	        if let Some(max) = filter.max_size {
442	            words.push(format!("max-size={max}"));
443	        }
444	    }
445	    if resume.is_some_and(|resume| resume.enabled) {
446	        words.push("resume".into());
447	    }
448	    if ignore_existing {
449	        words.push("ignore-existing".into());
450	    }
451	    if require_complete_scan {
452	        words.push("require-complete-scan".into());
453	    }
454	    words
455	}
