 117	///
 118	/// The parts become the log's file name, so the two IDs are limited to 1–64
 119	/// lowercase ASCII letters, digits, `-` and `_` — nothing that could leave
 120	/// the log folder, and no two keys a case-insensitive file system would take
 121	/// for one.
 122	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
