 130	impl LogKey {
 131	    pub fn new(
 132	        run_id: impl Into<String>,
 133	        participant: impl Into<String>,
 134	        role: Role,
 135	        attempt: u32,
 136	    ) -> eyre::Result<Self> {
 137	        let run_id = run_id.into();
 138	        let participant = participant.into();
 139	        check_id("run ID", &run_id)?;
 140	        check_id("participant ID", &participant)?;
 141	        Ok(Self {
 142	            run_id,
 143	            participant,
 144	            role,
 145	            attempt,
 146	        })
 147	    }
 148	
 149	    pub fn run_id(&self) -> &str {
 150	        &self.run_id
 151	    }
 152	
 153	    pub fn participant(&self) -> &str {
 154	        &self.participant
 155	    }
 156	
 157	    pub fn role(&self) -> Role {
 158	        self.role
 159	    }
 160	
 161	    pub fn attempt(&self) -> u32 {
 162	        self.attempt
 163	    }
 164	
 165	    /// The name every file of this log starts with:
 166	    /// `<run>.<participant>.<role>.<attempt>`.
 167	    pub fn file_stem(&self) -> String {
 168	        format!(
 169	            "{}.{}.{}.{}",
 170	            self.run_id,
 171	            self.participant,
 172	            self.role.as_str(),
 173	            self.attempt
 174	        )
 175	    }
 176	
 177	    /// The key a [`file_stem`](Self::file_stem) was made from; `None` for
 178	    /// any other name.
 179	    pub fn from_file_stem(stem: &str) -> Option<Self> {
 180	        let mut parts = stem.split('.');
 181	        let (run_id, participant, role, attempt) =
 182	            (parts.next()?, parts.next()?, parts.next()?, parts.next()?);
 183	        if parts.next().is_some() {
 184	            return None;
 185	        }
 186	        let number: u32 = attempt.parse().ok()?;
 187	        // `parse` also takes "+1" and "01", which `file_stem` never writes.
 188	        if number.to_string() != attempt {
 189	            return None;
 190	        }
 191	        Self::new(run_id, participant, Role::parse(role)?, number).ok()
 192	    }
 193	}
 194	
 195	fn check_id(what: &str, id: &str) -> eyre::Result<()> {
 196	    let allowed = |byte: u8| {
 197	        byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-' || byte == b'_'
 198	    };
 199	    if id.is_empty() || id.len() > LONGEST_ID || !id.bytes().all(allowed) {
 200	        eyre::bail!(
 201	            "a job log's {what} must be 1–{LONGEST_ID} lowercase letters, digits, '-' or '_' (got {id:?})"
 202	        );
 203	    }
 204	    Ok(())
 205	}
