 392	impl LogWriter {
 393	    /// Start the log `key` in `dir`, recording `run-start` with `run`.
 394	    /// Finishing it later prunes `dir` to the newest `keep` finished logs.
 395	    ///
 396	    /// Returns at once: the folder and files are made on the writer's
 397	    /// thread, and a failure there leaves an incomplete log, never an error.
 398	    pub fn start(dir: &Path, key: LogKey, run: RunInfo, keep: usize) -> Self {
