 402	    fn start_tuned(dir: &Path, key: LogKey, run: RunInfo, tuning: Tuning) -> Self {
 403	        let (tx, rx) = flume::bounded(tuning.queue_depth);
 404	        let started_ms = now_ms();
 405	        let dir = dir.to_path_buf();
 406	        let spawned = std::thread::Builder::new()
 407	            .name("blit-job-log".into())
 408	            .spawn(move || write_log(dir, key, run, started_ms, rx, tuning));
 409	        let (thread, spawn_error) = match spawned {
 410	            Ok(thread) => (Some(thread), None),
 411	            Err(error) => (
 412	                None,
 413	                Some(format!("could not start the log writer: {error}")),
 414	            ),
 415	        };
 416	        Self {
 417	            sender: LogSender { tx },
 418	            thread,
 419	            spawn_error,
 420	        }
 421	    }
