 435	    /// Close the log: record `run-end`, compress the log into place and
 436	    /// prune the folder. Blocks until done — compressing a large log takes
 437	    /// a moment — so async code calls it through `spawn_blocking`.
 438	    pub fn finish(mut self, outcome: Outcome, detail: Option<String>) -> LogReport {
 439	        let Some(thread) = self.thread.take() else {
 440	            return LogReport {
 441	                path: None,
 442	                complete: false,
 443	                problem: self.spawn_error.take(),
 444	            };
 445	        };
 446	        let _ = self.sender.tx.send(Msg::Finish { outcome, detail });
 447	        thread.join().unwrap_or_else(|_| LogReport {
 448	            path: None,
 449	            complete: false,
 450	            problem: Some("the log writer stopped unexpectedly".into()),
 451	        })
 452	    }
 453	}
