 481	/// The writer thread.
 482	fn write_log(
 483	    dir: PathBuf,
 484	    key: LogKey,
 485	    run: RunInfo,
 486	    started_ms: u64,
 487	    rx: flume::Receiver<Msg>,
 488	    tuning: Tuning,
 489	) -> LogReport {
 490	    #[cfg(test)]
 491	    if let Some(gate) = &tuning.start_gate {
 492	        let _ = gate.recv();
 493	    }
 494	    let mut writer = Writer::open(dir, key.file_stem(), &tuning);
 495	    writer.append(
 496	        started_ms,
 497	        EventBody::RunStart(Box::new(RunStart {
 498	            format: FORMAT.into(),
 499	            version: VERSION,
 500	            run_id: key.run_id,
 501	            participant: key.participant,
 502	            role: key.role,
 503	            attempt: key.attempt,
 504	            host: hostname::get()
 505	                .map(|name| name.to_string_lossy().into_owned())
 506	                .unwrap_or_default(),
 507	            build: crate::transfer_session::session_build_id().into(),
 508	            run,
 509	        })),
 510	    );
 511	    let (outcome, detail) = loop {
 512	        match rx.recv_timeout(writer.until_sync(tuning.sync_interval)) {
 513	            Ok(Msg::Event { ts_ms, body }) => {
 514	                let phase = matches!(body, EventBody::Phase { .. });
 515	                writer.append(ts_ms, body);
 516	                if phase || writer.until_sync(tuning.sync_interval).is_zero() {
 517	                    writer.sync();
 518	                }
 519	            }
 520	            Ok(Msg::Finish { outcome, detail }) => break (outcome, detail),
 521	            Err(flume::RecvTimeoutError::Timeout) => writer.sync(),
 522	            Err(flume::RecvTimeoutError::Disconnected) => {
 523	                break (Outcome::Interrupted, Some(UNCLOSED_NOTE.into()))
 524	            }
 525	        }
 526	    };
 527	    // A handle still recording now fails at once instead of waiting on a
 528	    // queue no one drains.
 529	    drop(rx);
 530	    writer.append(now_ms(), EventBody::RunEnd { outcome, detail });
 531	    writer.sync();
 532	    writer.finish(tuning.keep)
 533	}
