 535	/// The writer thread's state for one log.
 536	struct Writer {
 537	    dir: PathBuf,
 538	    stem: String,
 539	    /// The sidecar lock, held from opening the log until it is finished.
 540	    lock: Option<File>,
 541	    /// The partial being appended to; `None` once logging has stopped.
 542	    file: Option<PartialFile>,
 543	    report: LogReport,
 544	}
 545	
 546	impl Writer {
 547	    fn open(dir: PathBuf, stem: String, tuning: &Tuning) -> Self {
 548	        let mut writer = Writer {
 549	            dir,
 550	            stem,
 551	            lock: None,
 552	            file: None,
 553	            report: LogReport::default(),
 554	        };
 555	        match open_partial(&writer.dir, &writer.stem) {
 556	            Ok((lock, file)) => {
 557	                writer.report.path = Some(path_of(&writer.dir, &writer.stem, PARTIAL_SUFFIX));
 558	                writer.lock = Some(lock);
 559	                writer.file = Some(PartialFile {
 560	                    out: BufWriter::with_capacity(64 * 1024, file),
 561	                    line: Vec::new(),
 562	                    next_seq: 0,
 563	                    unsynced: false,
 564	                    last_sync: Instant::now(),
 565	                    #[cfg(test)]
 566	                    fail_at_seq: tuning.fail_at_seq,
 567	                });
 568	            }
 569	            Err(error) => {
 570	                writer.report.problem = Some(format!(
 571	                    "could not start the log in {}: {error}",
 572	                    writer.dir.display()
 573	                ))
 574	            }
 575	        }
 576	        #[cfg(not(test))]
 577	        let _ = tuning;
 578	        writer
 579	    }
 580	
 581	    fn append(&mut self, ts_ms: u64, body: EventBody) {
 582	        let Some(file) = self.file.as_mut() else {
 583	            return;
 584	        };
 585	        if let Err(error) = file.append(ts_ms, body) {
 586	            self.stop(error);
 587	        }
 588	    }
 589	
 590	    fn sync(&mut self) {
 591	        let Some(file) = self.file.as_mut() else {
 592	            return;
 593	        };
 594	        if !file.unsynced {
 595	            return;
 596	        }
 597	        if let Err(error) = file.sync() {
 598	            self.stop(error);
 599	        }
 600	    }
 601	
 602	    /// How long until what was written is due to be synced.
 603	    fn until_sync(&self, interval: Duration) -> Duration {
 604	        match &self.file {
 605	            Some(file) if file.unsynced => interval.saturating_sub(file.last_sync.elapsed()),
 606	            _ => IDLE_WAIT,
 607	        }
 608	    }
 609	
 610	    /// Logging stops at the first write that fails; the transfer goes on.
 611	    fn stop(&mut self, error: io::Error) {
 612	        let reason = format!("could not write the log: {error}");
 613	        if let Some(mut file) = self.file.take() {
 614	            // Best effort. The failed write may have left part of a line, so
 615	            // end it first and the marker stands as a line of its own.
 616	            let _ = file.out.write_all(b"\n").and_then(|()| {
 617	                file.append(
 618	                    now_ms(),
 619	                    EventBody::LogIncomplete {
 620	                        reason: reason.clone(),
 621	                    },
 622	                )?;
 623	                file.sync()
 624	            });
 625	        }
 626	        self.report.problem.get_or_insert(reason);
 627	    }
 628	
 629	    fn finish(mut self, keep: usize) -> LogReport {
 630	        self.report.complete = self.file.is_some();
 631	        // Close the partial before compressing it; it was synced already.
 632	        drop(self.file.take());
 633	        let Some(lock) = self.lock.take() else {
 634	            return self.report;
 635	        };
 636	        match compress_into_place(&self.dir, &self.stem) {
 637	            Ok(finished) => self.report.path = Some(finished),
 638	            Err(error) => {
 639	                self.report.problem.get_or_insert_with(|| {
 640	                    format!("could not finish the log (the next start finishes it): {error}")
 641	                });
 642	                return self.report;
 643	            }
 644	        }
 645	        drop(lock);
 646	        let _ = fs::remove_file(path_of(&self.dir, &self.stem, LOCK_SUFFIX));
 647	        if let Err(error) = prune(&self.dir, keep) {
 648	            log::warn!("job logs: pruning {} failed: {error}", self.dir.display());
 649	        }
 650	        self.report
 651	    }
 652	}
 653	
 654	struct PartialFile {
 655	    out: BufWriter<File>,
 656	    /// Each event is serialized here first, so the file only ever receives
 657	    /// whole lines.
 658	    line: Vec<u8>,
 659	    next_seq: u64,
 660	    unsynced: bool,
 661	    last_sync: Instant,
 662	    #[cfg(test)]
 663	    fail_at_seq: Option<u64>,
 664	}
 665	
 666	impl PartialFile {
 667	    fn append(&mut self, ts_ms: u64, body: EventBody) -> io::Result<()> {
 668	        self.line.clear();
 669	        serde_json::to_writer(
 670	            &mut self.line,
 671	            &Event {
 672	                ts_ms,
 673	                seq: self.next_seq,
 674	                body,
 675	            },
 676	        )?;
 677	        self.line.push(b'\n');
 678	        #[cfg(test)]
 679	        if self.fail_at_seq == Some(self.next_seq) {
 680	            // Half the line reaches the file, as a write cut short by a full
 681	            // disk leaves it.
 682	            self.fail_at_seq = None;
 683	            self.out.write_all(&self.line[..self.line.len() / 2])?;
 684	            return Err(io::Error::other("injected write failure"));
 685	        }
 686	        self.out.write_all(&self.line)?;
 687	        self.next_seq += 1;
 688	        self.unsynced = true;
 689	        Ok(())
 690	    }
 691	
 692	    fn sync(&mut self) -> io::Result<()> {
 693	        self.out.flush()?;
 694	        self.out.get_ref().sync_data()?;
 695	        self.unsynced = false;
 696	        self.last_sync = Instant::now();
 697	        Ok(())
 698	    }
 699	}
