 701	/// Take the key's lock and create its partial. Fails rather than touch a
 702	/// log another writer owns or one this key already has.
 703	fn open_partial(dir: &Path, stem: &str) -> io::Result<(File, File)> {
 704	    fs::create_dir_all(dir)?;
 705	    let lock_path = path_of(dir, stem, LOCK_SUFFIX);
 706	    let lock = open_lock_file(&lock_path)?;
 707	    match lock.try_lock() {
 708	        Ok(()) => {}
 709	        Err(TryLockError::WouldBlock) => {
 710	            return Err(io::Error::other("another writer has this log open"))
 711	        }
 712	        Err(TryLockError::Error(error)) => return Err(error),
 713	    }
 714	    let created = if path_of(dir, stem, FINISHED_SUFFIX).exists() {
 715	        Err(io::Error::new(
 716	            io::ErrorKind::AlreadyExists,
 717	            "this run already has a finished log",
 718	        ))
 719	    } else {
 720	        // A partial already here is an earlier writer's record of this key;
 721	        // never append to it or truncate it.
 722	        OpenOptions::new()
 723	            .write(true)
 724	            .create_new(true)
 725	            .open(path_of(dir, stem, PARTIAL_SUFFIX))
 726	    };
 727	    match created {
 728	        Ok(file) => Ok((lock, file)),
 729	        Err(error) => {
 730	            drop(lock);
 731	            let _ = fs::remove_file(&lock_path);
 732	            Err(error)
 733	        }
 734	    }
 735	}
 736	
 737	fn open_lock_file(path: &Path) -> io::Result<File> {
 738	    OpenOptions::new()
 739	        .write(true)
 740	        .create(true)
 741	        .truncate(false)
 742	        .open(path)
 743	}
 744	
 745	fn path_of(dir: &Path, stem: &str, suffix: &str) -> PathBuf {
 746	    dir.join(format!("{stem}{suffix}"))
 747	}
 748	
 749	/// Compress the partial into `<stem>.jsonl.gz` — through a temp file and one
 750	/// rename, so a reader or a crash sees either no finished log or a whole
 751	/// one — then remove the partial. The finished log keeps the partial's
 752	/// modified time, so pruning orders a recovered log by when its run wrote.
 753	fn compress_into_place(dir: &Path, stem: &str) -> io::Result<PathBuf> {
 754	    let partial = path_of(dir, stem, PARTIAL_SUFFIX);
 755	    let temp = path_of(dir, stem, TEMP_SUFFIX);
 756	    let finished = path_of(dir, stem, FINISHED_SUFFIX);
 757	    if let Err(error) = write_compressed(&partial, &temp, &finished) {
 758	        let _ = fs::remove_file(&temp);
 759	        return Err(error);
 760	    }
 761	    sync_dir(dir);
 762	    // The finished log is whole now; a partial left by a failure here is
 763	    // removed by `recover`.
 764	    if let Err(error) = fs::remove_file(&partial) {
 765	        log::warn!(
 766	            "job logs: could not remove {} after finishing it: {error}",
 767	            partial.display()
 768	        );
 769	    }
 770	    Ok(finished)
 771	}
 772	
 773	fn write_compressed(partial: &Path, temp: &Path, finished: &Path) -> io::Result<()> {
 774	    let mut input = File::open(partial)?;
 775	    let modified = input.metadata()?.modified()?;
 776	    let mut encoder = GzEncoder::new(BufWriter::new(File::create(temp)?), Compression::fast());
 777	    io::copy(&mut input, &mut encoder)?;
 778	    let output = encoder
 779	        .finish()?
 780	        .into_inner()
 780	        .into_inner()
 781	        .map_err(|error| error.into_error())?;
 782	    output.set_modified(modified)?;
 783	    output.sync_all()?;
 784	    drop(output);
 785	    fs::rename(temp, finished)
 786	}
