 788	/// Make a rename in `dir` durable (POSIX); Windows has no directory handle
 789	/// to sync and needs none.
 790	fn sync_dir(dir: &Path) {
 791	    #[cfg(unix)]
 792	    if let Ok(handle) = File::open(dir) {
 793	        let _ = handle.sync_all();
 794	    }
 795	    #[cfg(not(unix))]
 796	    let _ = dir;
 797	}
