 799	/// What [`recover`] did.
 800	#[derive(Clone, Debug, Default, PartialEq, Eq)]
 801	pub struct Recovery {
 802	    /// Logs this call finished, closed as interrupted unless they already
 803	    /// held their `run-end`.
 804	    pub finished: Vec<PathBuf>,
 805	    /// Partials left alone because a running writer still owns them.
 806	    pub live: usize,
 807	    /// Logs that could not be recovered, and why; they stay as they are for
 808	    /// the next attempt.
 809	    pub problems: Vec<String>,
 810	}
 811	
 812	/// Finish every log in `dir` that a stopped process left behind (run at
 813	/// startup). A partial whose lock is free has no writer: it gets a `run-end`
 814	/// marked interrupted — unless it already ends with one, the crash having
 815	/// come while it was being compressed — and is compressed into place.
 816	/// Partials a running writer holds are left alone.
 817	pub fn recover(dir: &Path) -> Recovery {
 818	    let mut recovery = Recovery::default();
 819	    let entries = match fs::read_dir(dir) {
 820	        Ok(entries) => entries,
 821	        Err(error) if error.kind() == io::ErrorKind::NotFound => return recovery,
 822	        Err(error) => {
 823	            recovery
 824	                .problems
 825	                .push(format!("could not read {}: {error}", dir.display()));
 826	            return recovery;
 827	        }
 828	    };
 829	    let mut stems: Vec<String> = Vec::new();
 830	    for entry in entries.flatten() {
 831	        let name = entry.file_name();
 832	        let Some(name) = name.to_str() else { continue };
 833	        let Some(stem) = name
 834	            .strip_suffix(PARTIAL_SUFFIX)
 835	            .or_else(|| name.strip_suffix(TEMP_SUFFIX))
 836	        else {
 837	            continue;
 838	        };
 839	        if LogKey::from_file_stem(stem).is_some() && !stems.iter().any(|seen| seen == stem) {
 840	            stems.push(stem.to_string());
 841	        }
 842	    }
 843	    stems.sort();
 844	    for stem in stems {
 845	        match recover_one(dir, &stem) {
 846	            Ok(Recovered::Finished(path)) => recovery.finished.push(path),
 847	            Ok(Recovered::Live) => recovery.live += 1,
 848	            Ok(Recovered::Tidied) => {}
 849	            Err(error) => recovery.problems.push(format!("{stem}: {error}")),
 850	        }
 851	    }
 852	    recovery
 853	}
 854	
 855	enum Recovered {
 856	    Finished(PathBuf),
 857	    Live,
 858	    /// Only leftovers of a log already finished were removed.
 859	    Tidied,
 860	}
 861	
 862	fn recover_one(dir: &Path, stem: &str) -> io::Result<Recovered> {
 863	    let lock_path = path_of(dir, stem, LOCK_SUFFIX);
 864	    let lock = open_lock_file(&lock_path)?;
 865	    match lock.try_lock() {
 866	        Ok(()) => {}
 867	        Err(TryLockError::WouldBlock) => return Ok(Recovered::Live),
 868	        Err(TryLockError::Error(error)) => return Err(error),
 869	    }
 870	    let partial = path_of(dir, stem, PARTIAL_SUFFIX);
 871	    let recovered = if !partial.exists() {
 872	        // A temp file whose partial is gone.
 873	        remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
 874	        Recovered::Tidied
 875	    } else if path_of(dir, stem, FINISHED_SUFFIX).exists() {
 876	        // Finished before the crash; only removing the partial was lost.
 877	        fs::remove_file(&partial)?;
 878	        remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
 879	        Recovered::Tidied
 880	    } else {
 881	        close_interrupted(&partial)?;
 882	        Recovered::Finished(compress_into_place(dir, stem)?)
 883	    };
 884	    drop(lock);
 885	    let _ = fs::remove_file(&lock_path);
 886	    Ok(recovered)
 887	}
 888	
 889	fn remove_if_present(path: &Path) -> io::Result<()> {
 890	    match fs::remove_file(path) {
 891	        Err(error) if error.kind() != io::ErrorKind::NotFound => Err(error),
 892	        _ => Ok(()),
 893	    }
 894	}
