 896	/// Append `run-end` (interrupted) to a partial that lacks one, keeping the
 897	/// partial's modified time.
 898	fn close_interrupted(partial: &Path) -> io::Result<()> {
 899	    let mut last = None;
 900	    for line in open_log(partial)? {
 901	        if let LogLine::Event(event) = line? {
 902	            last = Some(event);
 903	        }
 904	    }
 905	    if let Some(Event {
 906	        body: EventBody::RunEnd { .. },
 907	        ..
 908	    }) = last
 909	    {
 910	        return Ok(());
 911	    }
 912	    let mut file = OpenOptions::new().read(true).append(true).open(partial)?;
 913	    let modified = file.metadata()?.modified()?;
 914	    let mut line = Vec::new();
 915	    // A torn last line gets its end, so the new event is a line of its own.
 916	    if file.metadata()?.len() > 0 {
 917	        let mut byte = [0u8; 1];
 918	        file.seek(SeekFrom::End(-1))?;
 919	        file.read_exact(&mut byte)?;
 920	        if byte[0] != b'\n' {
 921	            line.push(b'\n');
 922	        }
 923	    }
 924	    serde_json::to_writer(
 925	        &mut line,
 926	        &Event {
 927	            ts_ms: now_ms(),
 928	            seq: last.map_or(0, |event| event.seq + 1),
 929	            body: EventBody::RunEnd {
 930	                outcome: Outcome::Interrupted,
 931	                detail: Some(RECOVERED_NOTE.into()),
 932	            },
 933	        },
 934	    )?;
 935	    line.push(b'\n');
 936	    file.write_all(&line)?;
 937	    file.sync_data()?;
 938	    drop(file);
 939	    filetime::set_file_mtime(partial, filetime::FileTime::from_system_time(modified))
 940	}
