 942	/// Remove finished logs in `dir` beyond the newest `keep`, newest by when
 943	/// each run last wrote to its log; returns the logs removed.
 944	///
 945	/// Holds `dir`'s prune lock throughout, so two runs finishing at once do not
 946	/// race, and touches only finished logs: never a partial (a running log, or
 947	/// one not yet recovered) and never a file that is not a log. Waits for the
 948	/// lock, so call it from blocking code.
 949	pub fn prune(dir: &Path, keep: usize) -> io::Result<Vec<PathBuf>> {
 950	    let lock = open_lock_file(&dir.join(PRUNE_LOCK))?;
 951	    lock.lock()?;
 952	    let mut finished = Vec::new();
 953	    for entry in fs::read_dir(dir)?.flatten() {
 954	        let name = entry.file_name();
 955	        let Some(stem) = name.to_str().and_then(|n| n.strip_suffix(FINISHED_SUFFIX)) else {
 956	            continue;
 957	        };
 958	        if LogKey::from_file_stem(stem).is_none() {
 959	            continue;
 960	        }
 961	        let Ok(meta) = entry.metadata() else { continue };
 962	        let Ok(modified) = meta.modified() else {
 963	            continue;
 964	        };
 965	        if meta.is_file() {
 966	            finished.push((modified, entry.path()));
 967	        }
 968	    }
 969	    // Newest first; names break ties so the order is the same every time.
 970	    finished.sort_by(|a, b| b.cmp(a));
 971	    let mut removed = Vec::new();
 972	    for (_, path) in finished.into_iter().skip(keep) {
 973	        match fs::remove_file(&path) {
 974	            Ok(()) => removed.push(path),
 975	            Err(error) => log::warn!("job logs: could not prune {}: {error}", path.display()),
 976	        }
 977	    }
 978	    Ok(removed)
 979	}
