 981	/// The log for `key` in `dir`: its finished file, or the partial of a run
 982	/// still going (or not yet recovered); `None` if there is neither.
 983	pub fn find_log(dir: &Path, key: &LogKey) -> Option<FoundLog> {
 984	    let stem = key.file_stem();
 985	    let finished = path_of(dir, &stem, FINISHED_SUFFIX);
 986	    let partial = path_of(dir, &stem, PARTIAL_SUFFIX);
 987	    let found = |path: PathBuf, finished: bool| FoundLog {
 988	        key: key.clone(),
 989	        path,
 990	        finished,
 991	    };
 992	    // Finished, partial, then finished again: a run that finishes between the
