1013	/// Every log in `dir` for the run `run_id` — in `role` only, when given —
1014	/// ordered by role, participant and attempt. Errors only when `run_id`
1015	/// cannot name a log or `dir` cannot be read; a missing `dir` holds no logs.
1016	pub fn logs_for_run(dir: &Path, run_id: &str, role: Option<Role>) -> eyre::Result<Vec<FoundLog>> {
1017	    check_id("run ID", run_id)?;
1018	    let entries = match fs::read_dir(dir) {
1019	        Ok(entries) => entries,
1020	        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
1021	        Err(error) => return Err(eyre::Report::new(error)),
1022	    };
1023	    let mut found: Vec<FoundLog> = Vec::new();
1024	    for entry in entries.flatten() {
1025	        let name = entry.file_name();
1026	        let Some(name) = name.to_str() else { continue };
1027	        let (stem, finished) = if let Some(stem) = name.strip_suffix(FINISHED_SUFFIX) {
1028	            (stem, true)
1029	        } else if let Some(stem) = name.strip_suffix(PARTIAL_SUFFIX) {
1030	            (stem, false)
1031	        } else {
1032	            continue;
1033	        };
1034	        let Some(key) = LogKey::from_file_stem(stem) else {
1035	            continue;
1036	        };
1037	        if key.run_id != run_id || role.is_some_and(|role| role != key.role) {
1038	            continue;
1039	        }
1040	        // A run caught between finishing and removing its partial shows
1041	        // once, as finished.
1042	        if let Some(seen) = found.iter_mut().find(|seen| seen.key == key) {
1043	            if finished {
1044	                *seen = FoundLog {
1045	                    key,
1046	                    path: entry.path(),
1047	                    finished,
1048	                };
1049	            }
1050	            continue;
1051	        }
1052	        found.push(FoundLog {
1053	            key,
1054	            path: entry.path(),
1055	            finished,
1056	        });
1057	    }
1058	    found.sort_by(|a, b| {
1059	        (a.key.role.as_str(), &a.key.participant, a.key.attempt).cmp(&(
1060	            b.key.role.as_str(),
1061	            &b.key.participant,
1062	            b.key.attempt,
1063	        ))
1064	    });
1065	    Ok(found)
1066	}
