1084	fn describe(body: &EventBody) -> String {
1085	    let seconds = |ms: u64| format!("{:.1}s", ms as f64 / 1000.0);
1086	    match body {
1087	        EventBody::RunStart(start) => {
1088	            let host = if start.host.is_empty() {
1089	                &start.participant
1090	            } else {
1091	                &start.host
1092	            };
1093	            let mut text = format!(
1094	                "start    {} {} -> {} (job {}, {} on {host}, attempt {}, blit {})",
1095	                start.run.verb,
1096	                start.run.source,
1097	                start.run.destination,
1098	                start.run_id,
1099	                start.role.as_str(),
1100	                start.attempt,
1101	                start.build,
1102	            );
1103	            if !start.run.options.is_empty() {
1104	                text.push_str(&format!(" options: {}", start.run.options.join(" ")));
1105	            }
1106	            text
1107	        }
1108	        EventBody::Phase { name, state } => {
1109	            let state = match state {
1110	                PhaseState::Start => "started",
1111	                PhaseState::End => "ended",
1112	            };
1113	            format!("phase    {name} {state}")
1114	        }
1115	        EventBody::FileCopied { path, bytes } => match bytes {
1116	            Some(bytes) => format!("copied   {path} ({})", crate::display::format_bytes(*bytes)),
1117	            None => format!("copied   {path}"),
1118	        },
1119	        EventBody::FileSent { path } => format!("sent     {path}"),
1120	        EventBody::FileDeleted { path } => format!("deleted  {path}"),
1121	        EventBody::FileFailed { path, reason } => format!("FAILED   {path}: {reason}"),
1122	        EventBody::Stall { idle_ms, detail } => {
1123	            format!("stall    nothing moved for {}: {detail}", seconds(*idle_ms))
1124	        }
1125	        EventBody::Diagnostic { message } => format!("info     {message}"),
1126	        EventBody::Summary(summary) => format!(
1127	            "summary  {} copied ({}), {} deleted, {} failed, in {}",
1128	            summary.files_copied,
1129	            crate::display::format_bytes(summary.bytes_copied),
1130	            summary.files_deleted,
1131	            summary.files_failed,
1132	            seconds(summary.elapsed_ms),
1133	        ),
1134	        EventBody::RunEnd { outcome, detail } => {
1135	            let outcome = match outcome {
1136	                Outcome::Ok => "ok",
1137	                Outcome::Failed => "failed",
1138	                Outcome::Cancelled => "cancelled",
1139	                Outcome::Interrupted => "interrupted",
1140	            };
1141	            match detail {
1142	                Some(detail) => format!("end      {outcome}: {detail}"),
1143	                None => format!("end      {outcome}"),
1144	            }
1145	        }
1146	        EventBody::LogIncomplete { reason } => {
1147	            format!("LOG INCOMPLETE  {reason}; nothing after this was kept")
1148	        }
1149	        EventBody::Unknown => "unknown  an event from a newer blit".into(),
1150	    }
1151	}
