   535	/// The writer thread's state for one log.
   536	struct Writer {
   537	    dir: PathBuf,
   538	    stem: String,
   539	    /// The sidecar lock, held from opening the log until it is finished.
   540	    lock: Option<File>,
   541	    /// The partial being appended to; `None` once logging has stopped.
   542	    file: Option<PartialFile>,
   543	    report: LogReport,
