   556	            Ok((lock, file)) => {
   557	                writer.report.path = Some(path_of(&writer.dir, &writer.stem, PARTIAL_SUFFIX));
   558	                writer.lock = Some(lock);
   559	                writer.file = Some(PartialFile {
   560	                    out: BufWriter::with_capacity(64 * 1024, file),
   561	                    line: Vec::new(),
   562	                    next_seq: 0,
   563	                    unsynced: false,
   564	                    last_sync: Instant::now(),
   565	                    #[cfg(test)]
   566	                    fail_at_seq: tuning.fail_at_seq,
   567	                });
   568	            }
   569	            Err(error) => {
   570	                writer.report.problem = Some(format!(
   571	                    "could not start the log in {}: {error}",
   572	                    writer.dir.display()
   573	                ))
   574	            }
   575	        }
   576	        #[cfg(not(test))]
   577	        let _ = tuning;
   578	        writer
   579	    }
   580	
   581	    fn append(&mut self, ts_ms: u64, body: EventBody) {
   582	        let Some(file) = self.file.as_mut() else {
   583	            return;
   584	        };
   585	        if let Err(error) = file.append(ts_ms, body) {
   586	            self.stop(error);
   587	        }
   588	    }
   589	
   590	    fn sync(&mut self) {
   591	        let Some(file) = self.file.as_mut() else {
   592	            return;
   593	        };
