   621	                    },
   622	                )?;
   623	                file.sync()
   624	            });
   625	        }
   626	        self.report.problem.get_or_insert(reason);
   627	    }
   628	
   629	    fn finish(mut self, keep: usize) -> LogReport {
   630	        self.report.complete = self.file.is_some();
