  1155	/// This machine's participant ID, kept in `dir`: made on first use (128
  1156	/// random bits as lowercase hex) and read back after. Host names change; this
  1157	/// does not.
  1158	pub fn machine_id(dir: &Path) -> io::Result<String> {
  1159	    let path = dir.join(MACHINE_ID_FILE);
  1160	    if !path.exists() {
  1161	        use rand::{rngs::SysRng, TryRng};
  1162	        let mut bits = [0u8; 16];
  1163	        SysRng
  1164	            .try_fill_bytes(&mut bits)
  1165	            .map_err(|error| io::Error::other(format!("system RNG unavailable: {error}")))?;
  1166	        let id: String = bits.iter().map(|byte| format!("{byte:02x}")).collect();
  1167	        fs::create_dir_all(dir)?;
  1168	        match OpenOptions::new().write(true).create_new(true).open(&path) {
  1169	            Ok(mut file) => {
  1170	                file.write_all(format!("{id}\n").as_bytes())?;
  1171	                file.sync_all()?;
  1172	            }
  1173	            // Another process made it first; read theirs.
  1174	            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
  1175	            Err(error) => return Err(error),
  1176	        }
  1177	    }
  1178	    let text = fs::read_to_string(&path)?;
  1179	    let id = text.trim();
  1180	    if check_id("machine ID", id).is_err() {
  1181	        return Err(io::Error::new(
  1182	            io::ErrorKind::InvalidData,
  1183	            format!("{} does not hold a machine ID", path.display()),
  1184	        ));
  1185	    }
  1186	    Ok(id.to_string())
  1187	}
