 /// Resolve a transfer's terminal outcome from its three racing
 /// conditions, giving handler completion priority (audit-10).
 ///
 /// Extracted for `delegated_pull` (R30-F2 / m-jobs-1) and generalized
 /// in w4-3 to be the single owner of the biased select every transfer
 /// RPC races through — `delegated_pull` calls it directly (handler
 /// output `bool`); the served `Transfer` session goes through
 /// [`resolve_transfer_session_outcome`] (handler output
 /// `Result<(), Status>`).
 ///
 /// The select is `biased` with the **handler branch first**: when the
 /// handler future is `Ready`, its result wins even if the cancel token
 /// has also just fired or the client just hung up. A handler that is
 /// still `Pending` yields to a client hangup (only when `!detach`) or a
 /// `CancelJob` cancel, both of which resolve to `None` so the caller
 /// records the cancellation.
 ///
 /// Pre-audit-10 the cancel branch was evaluated before the handler, so a
 /// transfer that completed at the same instant `CancelJob` fired its
 /// token was mis-recorded as "cancelled via CancelJob" despite having
 /// actually succeeded. Ordering completion first makes a real result
 /// (success *or* failure) authoritative over a simultaneous cancel.
 ///
 /// Returns `Some(output)` when the handler completed, or `None` for a
 /// client hangup or cancel.
 async fn resolve_transfer_outcome<T, H, C, K>(
     handler: H,
     tx_closed: C,
     cancelled: K,
     detach: bool,
 ) -> Option<T>
 where
     H: std::future::Future<Output = T>,
     C: std::future::Future<Output = ()>,
     K: std::future::Future<Output = ()>,
 {
     tokio::pin!(handler);
     tokio::select! {
         biased;
         output = &mut handler => Some(output),
         // ph-1c: a client hangup gets a bounded grace window before the
         // handler is dropped. The initiator legitimately disconnects
         // the instant it holds what it needs — for a served pull, right
         // after putting its scoring summary on the wire — so the frames
         // that complete this end's session are typically already in the
         // local receive buffer when the hangup signal fires. Dropping
         // the handler at that instant threw the summary away and
         // mis-scored every such transfer "client cancelled". A handler
         // that is genuinely mid-transfer cannot finish in the window
         // and still tears down as before, just `HANGUP_GRACE` later —
         // nobody is left to observe the difference. `CancelJob` stays
         // ungraced: it is an operator order to stop a running transfer.
         _ = tx_closed, if !detach => {
             tokio::time::timeout(HANGUP_GRACE, &mut handler).await.ok()
         }
         _ = cancelled => None,
     }
 }

 /// How long a raced transfer handler may keep running after its client
 /// hangs up, so a session whose terminal frames already arrived can
 /// finish absorbing them (see [`resolve_transfer_outcome`]).
 const HANGUP_GRACE: std::time::Duration = std::time::Duration::from_millis(500);

 /// Resolve a served `Transfer` session's terminal outcome, racing the
 /// handler against client hangup and the row's `CancelJob` token via
 /// [`resolve_transfer_outcome`] (the w4-3 shape the deleted
 /// push/pull_sync dispatchers used). On `CancelJob` it emits a framed
 /// `SessionError{CANCELLED}` on the response stream instead of a bare
 /// `Status::cancelled` (otp-4a review F1). The session speaks `TransferFrame`s, so the client reads the
 /// framed error — and the aborted session future can't send it itself
 /// once the select drops it, so the dispatcher does. A session that
 /// faults on its own already framed the reason; the trailing `Status`
 /// on that branch is belt-and-braces for a pre-frame transport break.
 async fn resolve_transfer_session_outcome<H>(
     handler: H,
     tx: &mpsc::Sender<Result<blit_core::generated::TransferFrame, Status>>,
     cancel_token: &CancellationToken,
     metrics: &TransferMetrics,
     // ph-1c: whether the session reached its terminal summary
     // (`ServedSessionRecorder::completed`). The initiator legitimately
     // hangs up as soon as it holds what it needs — often before this
     // end's teardown finishes — so a hangup (or a photo-finish
     // CancelJob, audit-10's own rationale) AFTER the terminal summary
     // is a completed transfer, not a cancel. Without this, every
     // served pull scored "client cancelled" on the daemon while the
     // client held a clean summary — dishonest jobs/metrics telemetry.
