   177	    /// Send a `TransferStarted` event onto the broadcast channel.
   178	    /// Called from each RPC dispatch site immediately after the
   179	    /// `ActiveJob` is registered, with the same values that
   180	    /// populated the row. A `SendError` return from `broadcast::Sender::send`
   181	    /// just means there are no current subscribers — that is the
   182	    /// normal state and we ignore it.
   183	    ///
   184	    /// Caller-passed values rather than re-reading from the
   185	    /// `ActiveJobGuard`: the dispatch site already has all the
   186	    /// inputs in scope as locals, and using them here avoids a
   187	    /// table lookup + clone on every transfer. Module/path are
   188	    /// empty strings for streaming RPCs at registration time;
   189	    /// that matches `GetState.active[]`'s view of the same row.
   190	    pub(crate) fn emit_transfer_started(
   191	        &self,
   192	        guard: &crate::active_jobs::ActiveJobGuard,
   193	        kind: ActiveJobKind,
   194	        peer: &str,
   195	        module: &str,
   196	        path: &str,
   197	    ) {
   198	        let event = DaemonEvent {
   199	            payload: Some(daemon_event::Payload::TransferStarted(TransferStarted {
   200	                transfer_id: guard.transfer_id().to_string(),
   201	                kind: kind.to_wire() as i32,
   202	                peer: peer.to_string(),
   203	                module: module.to_string(),
   204	                path: path.to_string(),
   205	                start_unix_ms: guard.start_unix_ms(),
   206	            })),
   207	        };
   208	        // c-5b: emit via ActiveJobs so the event lands in the
   209	        // per-row ring (for future replay) AND on the
   210	        // broadcast (for live subscribers). Both happen under
   211	        // the table lock — see emit_event rustdoc.
   212	        self.active_jobs
   213	            .emit_event(&self.events_tx, guard.transfer_id(), event);
   214	    }
