   216	    /// Clone of the broadcast sender, handed to spawn closures
   217	    /// that need to fire terminal `TransferComplete` /
   218	    /// `TransferError` events after `record_outcome` but before
   219	    /// the guard drops. The closures don't otherwise see `&self`,
   220	    /// so the dispatch site clones this once and moves the clone
   221	    /// into the spawned task. Each `broadcast::Sender::clone` is
   222	    /// an Arc bump; effectively free.
   223	    pub(crate) fn events_tx(&self) -> broadcast::Sender<DaemonEvent> {
   224	        self.events_tx.clone()
   225	    }
   226	}
