   228	/// Drive one tick of the c-4 progress emitter. For each row in the
   229	/// `active_jobs` table, computes throughput since the previous tick
   230	/// and broadcasts a `TransferProgress` event with the row's current
   231	/// byte count.
   232	///
   233	/// Factored as a free function so the daemon's tokio interval task
   234	/// can drive it on a timer AND tests can call it directly without
   235	/// standing up a runtime + timer.
   236	///
   237	/// Returns the number of events emitted (one per active row).
   238	pub(crate) fn tick_progress_once(
   239	    active_jobs: &crate::active_jobs::ActiveJobs,
   240	    events_tx: &broadcast::Sender<DaemonEvent>,
   241	) -> usize {
   242	    // c-5b: dispatch through `tick_progress_emit`, which
   243	    // builds AND broadcasts AND pushes to the per-row event
   244	    // ring all under the same table lock. The lock window
   245	    // serializes against c-3 terminal-event Drop (which also
   246	    // takes the table lock) and against c-5b subscribe
   247	    // snapshots (which use the same lock), so progress events
   248	    // can never be observed after a same-id terminal event
   249	    // and can never be missed/duplicated by replaying
   250	    // subscribers.
   251	    active_jobs.tick_progress_emit(events_tx, |sample| DaemonEvent {
   252	        payload: Some(daemon_event::Payload::TransferProgress(TransferProgress {
   253	            transfer_id: sample.transfer_id.clone(),
   254	            bytes_completed: sample.bytes_completed,
   255	            bytes_total: sample.bytes_total,
   256	            files_completed: sample.files_completed,
   257	            files_total: sample.files_total,
   258	            throughput_bps: sample.throughput_bps,
   259	        })),
   260	    })
   261	}
