   263	/// Spawn the long-running progress ticker. Called from the daemon
   264	/// binary's `main` after the service is constructed; the returned
   265	/// `JoinHandle` lives as long as the daemon process.
   266	///
   267	/// Tests don't spawn this — they call [`tick_progress_once`]
   268	/// directly so the test ordering is deterministic and doesn't pick
   269	/// up arbitrary background events.
   270	pub fn spawn_progress_ticker(svc: &BlitService) -> tokio::task::JoinHandle<()> {
   271	    let active_jobs = svc.active_jobs.clone();
   272	    let events_tx = svc.events_tx.clone();
   273	    tokio::spawn(async move {
   274	        let mut interval =
   275	            tokio::time::interval(std::time::Duration::from_millis(DEFAULT_PROGRESS_TICK_MS));
   276	        // Skip behavior: if the daemon is paused (e.g. by a long
   277	        // single-threaded operation) we don't want to fire a burst
   278	        // of catch-up ticks afterwards.
   279	        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
   280	        loop {
   281	            interval.tick().await;
   282	            let _ = tick_progress_once(&active_jobs, &events_tx);
   283	        }
   284	    })
   285	}
