   287	/// c-5a: decide whether a `DaemonEvent` should be forwarded to a
   288	/// subscriber whose `SubscribeRequest.transfer_id_filter` is set
   289	/// to `filter`. Empty filter accepts everything. Non-empty
   290	/// filter accepts only transfer-scoped events whose `transfer_id`
   291	/// matches.
   292	///
   293	/// Non-transfer-scoped events (future variants: `ModuleListChanged`,
   294	/// `DaemonHeartbeat`) bypass the filter entirely so a subscriber
   295	/// tracking a specific transfer still sees daemon-wide state
   296	/// updates relevant to context — they're cheap and provide
   297	/// orientation.
   298	pub(crate) fn event_matches_filter(event: &DaemonEvent, filter: &str) -> bool {
   299	    if filter.is_empty() {
   300	        return true;
   301	    }
   302	    // Exhaustive match over current variants. Future
   303	    // non-transfer-scoped variants (ModuleListChanged,
   304	    // DaemonHeartbeat) should be added with the explicit
   305	    // policy "bypass the filter and always forward" so
   306	    // subscribers tracking one transfer still see daemon-wide
   307	    // context. Adding any future variant here is a compile-
   308	    // forced decision — exactly what we want.
   309	    match event.payload.as_ref() {
   310	        Some(daemon_event::Payload::TransferStarted(e)) => e.transfer_id == filter,
   311	        Some(daemon_event::Payload::TransferProgress(e)) => e.transfer_id == filter,
   312	        Some(daemon_event::Payload::TransferComplete(e)) => e.transfer_id == filter,
   313	        Some(daemon_event::Payload::TransferError(e)) => e.transfer_id == filter,
   314	        None => false,
   315	    }
   316	}
