   318	/// Build the terminal event for a transfer that's draining. Called
   319	/// from each RPC's spawn closure after `record_outcome` and before
   320	/// `drop(job)`, with the same `(ok, error_message)` pair that the
   321	/// ActiveJobs ring records. Pairs with `emit_transfer_started` on
   322	/// the receive side: every transfer that emitted Started will also
   323	/// emit either Complete or Error.
   324	///
   325	/// Sourced from the guard so byte total and duration match what
   326	/// `GetState.recent[]` will surface on the same row.
   327	pub(crate) fn build_transfer_finished_event(
   328	    guard: &crate::active_jobs::ActiveJobGuard,
   329	    ok: bool,
   330	    error_message: Option<&str>,
   331	) -> DaemonEvent {
   332	    if ok {
   333	        let progress = guard.progress_snapshot();
   334	        DaemonEvent {
   335	            payload: Some(daemon_event::Payload::TransferComplete(TransferComplete {
   336	                transfer_id: guard.transfer_id().to_string(),
   337	                bytes: progress.bytes_completed,
   338	                files: progress.files_completed,
   339	                duration_ms: guard.elapsed_ms(),
   340	                tcp_fallback_used: progress.tcp_fallback_used,
   341	            })),
   342	        }
   343	    } else {
   344	        DaemonEvent {
   345	            payload: Some(daemon_event::Payload::TransferError(TransferError {
   346	                transfer_id: guard.transfer_id().to_string(),
   347	                message: error_message.unwrap_or("").to_string(),
   348	            })),
   349	        }
   350	    }
   351	}
