   369	
   370	    /// ONE_TRANSFER_PATH otp-4a: the daemon serves the unified session
   371	    /// by running `run_destination` as the Responder — the byte
   372	    /// RECEIVER of a client-initiated SOURCE push. Mirrors `push`:
   373	    /// register a jobs row, race the session against cancel/hangup, and
   374	    /// return the response stream immediately (the session runs in the
   375	    /// spawned task, feeding the `ReceiverStream`). Session refusals
   376	    /// travel to the peer as `SessionError` frames; the daemon-specific
   377	    /// module resolution + transport assembly live in `super::transfer`.
   378	    /// Contract: docs/TRANSFER_SESSION.md.
   379	    async fn transfer(
   380	        &self,
   381	        request: Request<tonic::Streaming<blit_core::generated::TransferFrame>>,
   382	    ) -> Result<Response<Self::TransferStream>, Status> {
   383	        let peer = peer_addr_string(&request);
   384	        let modules = Arc::clone(&self.modules);
   385	        let default_root = self.default_root.clone();
   386	        // Operator policy applies to served sessions exactly as it did
   387	        // to the old handlers: --force-grpc-data grants no TCP data
   388	        // plane (review otp-10a F3); --no-server-checksums refuses
   389	        // Checksum opens (otp-10b-1).
   390	        let policy = blit_core::transfer_session::ResponderPolicy {
   391	            force_in_stream: self.force_grpc_data,
   392	            refuse_checksum_compare: !self.server_checksums_enabled,
   393	        };
   394	        let (tx, rx) = mpsc::channel(32);
   395	        let inbound = request.into_inner();
   396	        let metrics = Arc::clone(&self.metrics);
   397	        let guard = Arc::clone(&metrics).enter_transfer();
   398	        // Jobs row: registered with a Push placeholder and an empty
   399	        // endpoint — the KIND and module/path all arrive in the
   400	        // SessionOpen, mid-handshake inside the session. The on_open
   401	        // hook below (review otp-10b-2 F4) fixes the row, counts the
   402	        // right metric, and emits the started event the moment the
   403	        // open resolves; the row supports CancelJob throughout.
   404	        let job = self.active_jobs.register(
   405	            ActiveJobKind::Push,
   406	            peer.clone(),
   407	            String::new(),
   408	            String::new(),
   409	        );
   410	        let started = std::time::Instant::now();
   411	        let events_tx = self.events_tx();
   412	        let started_emitted = Arc::new(std::sync::atomic::AtomicBool::new(false));
   413	        let on_open: Arc<super::transfer::OnSessionOpen> = {
   414	            let updater = job.updater();
   415	            let active_jobs = self.active_jobs.clone();
   416	            let events_tx = self.events_tx();
   417	            let metrics = Arc::clone(&self.metrics);
   418	            let peer = peer.clone();
   419	            let started_emitted = Arc::clone(&started_emitted);
   420	            Arc::new(move |kind: ActiveJobKind, module: &str, path: &str| {
   421	                // The metric counts at open-resolve — the first point
   422	                // the daemon knows push- from pull-equivalent. A
   423	                // session refused in the handshake counts nothing
   424	                // (the old dispatchers counted refusals as pushes).
   425	                match kind {
   426	                    ActiveJobKind::Push => metrics.inc_push(),
   427	                    _ => metrics.inc_pull(),
   428	                }
   429	                updater.set_kind_and_endpoint(kind, module.to_string(), path.to_string());
   430	                started_emitted.store(true, std::sync::atomic::Ordering::Release);
   431	                let event = DaemonEvent {
   432	                    payload: Some(daemon_event::Payload::TransferStarted(TransferStarted {
   433	                        transfer_id: updater.transfer_id().to_string(),
   434	                        kind: kind.to_wire() as i32,
   435	                        peer: peer.clone(),
   436	                        module: module.to_string(),
   437	                        path: path.to_string(),
   438	                        start_unix_ms: updater.start_unix_ms(),
   439	                    })),
   440	                };
   441	                active_jobs.emit_event(&events_tx, updater.transfer_id(), event);
   442	            })
   443	        };
   444	        let active_jobs = self.active_jobs.clone();
   445	        // ph-1c: dispatcher-owned session observer — it must outlive
   446	        // the raced responder future (see ServedSessionRecorder).
   447	        let recorder =
   448	            super::transfer::ServedSessionRecorder::new(self.perf_store.clone(), peer.clone());
   449	        let peer_for_task = peer;
   450	        // jl-1b: the job's log, owned by this dispatcher like the recorder.
   451	        let job_log = crate::job_logs::JobLog::new(self.job_logs.clone(), job.transfer_id());
   452	
   453	        tokio::spawn(async move {
   454	            let guard = guard;
   455	            let job = job;
   456	            let cancel_token = job.cancellation_token().clone();
   457	            let byte_progress = job.bytes_counter();
   458	            let job_progress = job.progress();
   459	            // Session variant: cancel surfaces as a framed
   460	            // SessionError{CANCELLED}, not a bare Status (review F1).
   461	            let (ok, err_msg) = resolve_transfer_session_outcome(
   462	                super::transfer::run_transfer_session(
   463	                    modules,
   464	                    default_root,
   465	                    inbound,
   466	                    tx.clone(),
   467	                    policy,
   468	                    byte_progress,
   469	                    job_progress,
   470	                    on_open,
   471	                    Arc::clone(&recorder),
   472	                    job_log.clone(),
   473	                ),
   474	                &tx,
   475	                &cancel_token,
   476	                &metrics,
   477	                || recorder.completed(),
   478	            )
   479	            .await;
   480	            // ph-1c: a hangup after the terminal summary was scored ok
   481	            // above but may have dropped the responder before its own
   482	            // `finish` — pin the jobs row to the summary's final counts
   483	            // (idempotent when the responder got there itself). Then
   484	            // append the daemon's own performance row.
   485	            if ok {
   486	                if let Some(summary) = recorder.terminal_summary() {
   487	                    job.progress().finish(
   488	                        summary.files_transferred,
   489	                        summary.bytes_transferred,
   490	                        summary.in_stream_carrier_used,
   491	                    );
   492	                }
   493	            }
   494	            recorder.record(ok);
   495	            // A session that died before its open resolved never fired
   496	            // the hook: emit the started event now — with the
   497	            // registration placeholders, the pre-cutover dispatch-time
   498	            // shape — so subscribers still see a paired
   499	            // started/finished sequence.
   500	            if !started_emitted.load(std::sync::atomic::Ordering::Acquire) {
   501	                let event = DaemonEvent {
   502	                    payload: Some(daemon_event::Payload::TransferStarted(TransferStarted {
   503	                        transfer_id: job.transfer_id().to_string(),
   504	                        kind: ActiveJobKind::Push.to_wire() as i32,
   505	                        peer: peer_for_task.clone(),
   506	                        module: String::new(),
   507	                        path: String::new(),
   508	                        start_unix_ms: job.start_unix_ms(),
   509	                    })),
   510	                };
   511	                active_jobs.emit_event(&events_tx, job.transfer_id(), event);
   512	            }
   513	            job.record_outcome(ok, err_msg.clone());
   514	            let finished_event = build_transfer_finished_event(&job, ok, err_msg.as_deref());
   515	            drop(job);
   516	            drop(guard);
   517	            let _ = events_tx.send(finished_event);
   518	            metrics.log_completion("transfer", started.elapsed(), ok);
   519	            // jl-1b: close the log last — compressing a large one takes a
   520	            // moment, and the job's row and events must not wait on it.
   521	            let summary = recorder.terminal_summary();
   522	            let (outcome, detail) = crate::job_logs::job_outcome(
   523	                ok,
   524	                err_msg.as_deref(),
   525	                cancel_token.is_cancelled(),
   526	                summary.as_ref().map_or(0, |summary| summary.files_failed),
   527	            );
   528	            job_log.close(outcome, detail, summary).await;
   529	        });
   530	
   531	        Ok(Response::new(ReceiverStream::new(rx)))
   532	    }
