   534	    async fn subscribe(
   535	        &self,
   536	        request: Request<SubscribeRequest>,
   537	    ) -> Result<Response<Self::SubscribeStream>, Status> {
   538	        let req = request.into_inner();
   539	        let transfer_id_filter = req.transfer_id_filter;
   540	        // c-5b: atomically register a broadcast Receiver AND
   541	        // snapshot the per-row event ring (if replay_recent &&
   542	        // filter is non-empty AND the row exists). Both happen
   543	        // under the table lock so no event can be observed
   544	        // both via replay and via broadcast — see emit_event /
   545	        // subscribe_with_ring rustdoc for the full ordering.
   546	        let (mut broadcast_rx, replay) = self.active_jobs.subscribe_with_ring(
   547	            &self.events_tx,
   548	            &transfer_id_filter,
   549	            req.replay_recent,
   550	        );
   551	
   552	        // c-5a round 2: per-subscriber forwarder. The round-1
   553	        // shape (returning `BroadcastStream::filter_map` directly)
   554	        // still advanced the subscriber's broadcast cursor
   555	        // through every event — so a `jobs watch <id>` consumer
   556	        // could be aborted with Lagged when unrelated transfers
   557	        // overflowed the global ring, even though the filter
   558	        // rejected those events anyway.
   559	        //
   560	        // Fix: spawn a task that eagerly drains the broadcast
   561	        // (cursor stays caught up independent of client read
   562	        // pace), applies the filter, and forwards only matching
   563	        // events into a bounded per-subscriber `mpsc`. The mpsc
   564	        // receiver is what tonic streams to the client.
   565	        //
   566	        // Lagged semantics now mean "the FORWARDER couldn't
   567	        // keep up with global event rate" — a daemon-side CPU
   568	        // problem, not "this client is slow on its filtered
   569	        // subset." If the client is slow on the matching
   570	        // subset the mpsc fills first, the forwarder's
   571	        // `send().await` blocks, and Lagged eventually fires
   572	        // through the normal broadcast over-capacity path —
   573	        // which is the correct "this client really is too
   574	        // slow" signal.
   575	        let (tx, rx) = mpsc::channel::<Result<DaemonEvent, Status>>(SUBSCRIBE_MPSC_CAPACITY);
   576	        tokio::spawn(async move {
   577	            // c-5b: drain replay events first (empty Vec when
   578	            // replay_recent=false or filter is empty or row
   579	            // doesn't exist). The forwarder then transitions
   580	            // to live broadcast forwarding. Note that replay
   581	            // events have ALREADY been deduped against the
   582	            // broadcast Receiver under the table lock — the
   583	            // ordering contract in `subscribe_with_ring` and
   584	            // `emit_event` ensures any event in `replay` is
   585	            // NOT also in `broadcast_rx`.
   586	            for event in replay {
   587	                if tx.send(Ok(event)).await.is_err() {
   588	                    // Client dropped before consuming replay.
   589	                    return;
   590	                }
   591	            }
   592	            loop {
   593	                // c-5a round 3: race broadcast recv against
   594	                // `tx.closed()` so the forwarder exits as soon
   595	                // as the client drops the stream — not only
   596	                // when a matching event happens to arrive.
   597	                // Without this race a filtered watcher that
   598	                // disconnects during a quiet period (no
   599	                // further matching events) leaks a task + a
   600	                // live broadcast Receiver indefinitely, since
   601	                // unrelated events are filtered with `continue`
   602	                // and never touch `tx`.
   603	                let recv = tokio::select! {
   604	                    biased;
   605	                    () = tx.closed() => break,
   606	                    recv = broadcast_rx.recv() => recv,
   607	                };
   608	                match recv {
   609	                    Ok(event) => {
   610	                        if !event_matches_filter(&event, &transfer_id_filter) {
   611	                            continue;
   612	                        }
   613	                        if tx.send(Ok(event)).await.is_err() {
   614	                            // Client dropped between filter and send.
   615	                            break;
   616	                        }
   617	                    }
   618	                    Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
   619	                        let _ = tx
