 840	    async fn list(&self, request: Request<ListRequest>) -> Result<Response<ListResponse>, Status> {
 841	        let req = request.into_inner();
 842	        let module = resolve_module(&self.modules, self.default_root.as_ref(), &req.module).await?;
 843	
 844	        let requested = if req.path.trim().is_empty() {
 845	            PathBuf::from(".")
 846	        } else {
 847	            resolve_relative_path(&req.path)?
 848	        };
 849	
 850	        let target = resolve_contained_path(&module, &requested)?;
 850	        let target = resolve_contained_path(&module, &requested)?;
 851	        let response_entries =
 852	            tokio::task::spawn_blocking(move || -> Result<Vec<FileInfo>, Status> {
 853	                let metadata = fs::metadata(&target)
 854	                    .map_err(|err| io_to_status(format!("stat {}", target.display()), err))?;
 855	
 856	                if metadata.is_file() {
 857	                    let name = requested
 858	                        .file_name()
 859	                        .map(|s| s.to_string_lossy().into_owned())
 860	                        .unwrap_or_else(|| ".".to_string());
 861	                    let info = FileInfo {
 862	                        name,
 863	                        is_dir: false,
 864	                        size: metadata.len(),
 865	                        mtime_seconds: blit_core::wire_metadata::mtime_seconds(&metadata)
 866	                            .unwrap_or(0),
 867	                    };
 868	                    Ok(vec![info])
 869	                } else if metadata.is_dir() {
 870	                    let mut infos = Vec::new();
 871	                    let entries = fs::read_dir(&target).map_err(|err| {
 872	                        io_to_status(format!("read_dir {}", target.display()), err)
 873	                    })?;
 874	                    for entry in entries {
 875	                        let entry = entry.map_err(|err| {
 876	                            io_to_status(format!("read_dir entry {}", target.display()), err)
 877	                        })?;
 878	                        let path = entry.path();
 879	                        let meta = entry.metadata().map_err(|err| {
 880	                            io_to_status(format!("metadata {}", path.display()), err)
 881	                        })?;
 882	                        let name = entry.file_name().to_string_lossy().into_owned();
 883	                        infos.push(FileInfo {
 884	                            name,
 885	                            is_dir: meta.is_dir(),
 886	                            size: meta.len(),
 887	                            mtime_seconds: blit_core::wire_metadata::mtime_seconds(&meta)
 888	                                .unwrap_or(0),
 889	                        });
 890	                    }
 891	                    infos.sort_by(|a, b| a.name.cmp(&b.name));
 892	                    Ok(infos)
 893	                } else {
 894	                    Err(Status::invalid_argument(format!(
 895	                        "unsupported path type for list: {}",
 896	                        target.display()
 897	                    )))
 898	                }
 899	            })
 900	            .await
 901	            .map_err(|err| internal_err("list task failed", err))??;
 902	
 903	        Ok(Response::new(ListResponse {
 904	            entries: response_entries,
 905	        }))
 906	    }
