 pub struct NoProbe;

 impl Probe for NoProbe {
     const ACTIVE: bool = false;
     #[inline(always)]
     fn record_bytes(&self, _delta: u64) {}
     #[inline(always)]
     fn note_write_blocked(&self, _nanos: u64) {}
 }

