 impl Probe for LiveProbe {
     const ACTIVE: bool = true;
     #[inline(always)]
     fn record_bytes(&self, delta: u64) {
         self.0.record_bytes(delta);
     }
     #[inline(always)]
     fn note_write_blocked(&self, nanos: u64) {
         self.0.add_write_blocked(nanos);
     }
 }

