+impl LogLines {
+    /// The lines of a log already [`decode`]d.
+    pub fn new(reader: Box<dyn BufRead + Send>) -> Self {
+        Self {
+            reader,
+            buf: Vec::new(),
+            line: 0,
+            done: false,
+        }
+    }
+}
+
 impl Iterator for LogLines {
     type Item = io::Result<LogLine>;

     fn next(&mut self) -> Option<Self::Item> {
         while !self.done {
             self.buf.clear();
             match self.reader.read_until(b'\n', &mut self.buf) {
                 Ok(0) => self.done = true,
                 Ok(_) => {
                     self.line += 1;
                     let ended = self.buf.ends_with(b"\n");
                     let text = self.buf.trim_ascii();
                     if text.is_empty() {
                         continue;
                     }
                     return Some(Ok(match serde_json::from_slice::<Event>(text) {
                         Ok(event) => LogLine::Event(event),
                         Err(_) => LogLine::Unreadable {
                             line: self.line,
                             torn: !ended,
                         },
                     }));
                 }
                 Err(error) => {
                     self.done = true;
                     return Some(Err(error));
                 }
             }
         }
         None
     }
 }

 fn now_ms() -> u64 {
     SystemTime::now()
         .duration_since(UNIX_EPOCH)
         .map_or(0, |since| {
             u64::try_from(since.as_millis()).unwrap_or(u64::MAX)
         })
 }

