+fn write_json_log(out: &mut impl Write, mut lines: Box<dyn BufRead + Send>) -> Result<()> {
+    let mut line = Vec::new();
+    loop {
+        line.clear();
+        if lines.read_until(b'\n', &mut line)? == 0 {
