   270	                        break;
   271	                    }
   272	                }
   273	                Some(job_log_chunk::Payload::Data(bytes)) => {
   274	                    let Some(tx) = &current else {
   275	                        fetched = Err(eyre::eyre!("the daemon sent log bytes before a log header"));
   276	                        break;
   277	                    };
