   279	                    if tx.send(Ok(bytes)).await.is_err() {
   280	                        break;
   281	                    }
   282	                }
   283	                None => {}
   284	            },
   285	            Ok(None) => break,
   286	            Err(status) => {
   287	                if let Some(tx) = &current {
   288	                    let _ = tx
   289	                        .send(Err(io::Error::other(status.message().to_string())))
   290	                        .await;
   291	                }
   292	                fetched = Err(eyre::eyre!(
   293	                    "reading the job log failed ({}): {}",
   294	                    status.code(),
   295	                    status.message()
   296	                ));
   297	                break;
   298	            }
   299	        }
   300	    }
   301	    drop(current);
   302	    drop(logs_tx);
   303	    let consumed = consumer
   304	        .await
   305	        .map_err(|error| eyre::eyre!("the log reader stopped: {error}"))?;
   306	    fetched?;
   307	    consumed
   308	}
