   310	/// One log's bytes as they arrive, read on a blocking thread.
   311	struct ChunkReader {
   312	    rx: tokio::sync::mpsc::Receiver<io::Result<Vec<u8>>>,
   313	    chunk: Vec<u8>,
   314	    pos: usize,
   315	}
   316	
   317	impl ChunkReader {
   318	    fn new(rx: tokio::sync::mpsc::Receiver<io::Result<Vec<u8>>>) -> Self {
   319	        Self {
   320	            rx,
   321	            chunk: Vec::new(),
   322	            pos: 0,
   323	        }
   324	    }
   325	}
