   327	impl Read for ChunkReader {
   328	    fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
   329	        while self.pos == self.chunk.len() {
   330	            match self.rx.blocking_recv() {
   331	                Some(Ok(chunk)) => {
   332	                    self.chunk = chunk;
   333	                    self.pos = 0;
   334	                }
   335	                Some(Err(error)) => return Err(error),
   336	                None => return Ok(0),
   337	            }
   338	        }
   339	        let n = out.len().min(self.chunk.len() - self.pos);
   340	        out[..n].copy_from_slice(&self.chunk[self.pos..self.pos + n]);
