    39	/// as text or, with `--json`, as its JSON lines.
    40	async fn run_jobs_log(args: JobsLogArgs) -> Result<()> {
    41	    let remote = RemoteEndpoint::parse(&args.remote)
    42	        .with_context(|| format!("parsing remote endpoint '{}'", args.remote))?;
    43	    let role = args.role.map(|role| match role {
    44	        LogRole::Initiator => Role::Initiator,
    45	        LogRole::Source => Role::Source,
    46	        LogRole::Destination => Role::Destination,
    47	    });
    48	    let json = args.json;
    49	    let mut first = true;
    50	    jobs::read_job_logs(&remote, &args.transfer_id, role, move |header, lines| {
    51	        let stdout = std::io::stdout();
    52	        let mut out = stdout.lock();
    53	        if json {
    54	            write_json_log(&mut out, lines)?;
    55	        } else {
    56	            if !first {
    57	                writeln!(out)?;
    58	            }
    59	            write_text_log(&mut out, &header, lines)?;
