    68	fn write_text_log(
    69	    out: &mut impl Write,
    70	    header: &JobLogHeader,
    71	    lines: Box<dyn BufRead + Send>,
    72	) -> Result<()> {
    73	    let unfinished = if header.finished {
    74	        ""
    75	    } else {
    76	        " — not finished: the job is running, or the daemon stopped during it"
    77	    };
    78	    writeln!(
    79	        out,
    80	        "== {} log from machine {} (attempt {}){unfinished} ==",
    81	        header.role, header.participant, header.attempt
    82	    )?;
    83	    for line in LogLines::new(lines) {
    84	        match line? {
    85	            LogLine::Event(event) => writeln!(out, "{}", job_log::text_line(&event))?,
    86	            LogLine::Unreadable { line, torn: true } => {
    87	                writeln!(out, "(line {line} was cut short)")?
    88	            }
    89	            LogLine::Unreadable { line, torn: false } => {
    90	                writeln!(out, "(line {line} is not a log event)")?
    91	            }
    92	        }
    93	    }
    94	    Ok(())
    95	}
