    97	/// The log's lines as stored. A log cut short mid-line still ends with a
    98	/// newline, so the next log starts on a line of its own.
    99	fn write_json_log(out: &mut impl Write, mut lines: Box<dyn BufRead + Send>) -> Result<()> {
   100	    let mut line = Vec::new();
   101	    loop {
   102	        line.clear();
   103	        if lines.read_until(b'\n', &mut line)? == 0 {
   104	            return Ok(());
   105	        }
   106	        out.write_all(&line)?;
   107	        if !line.ends_with(b"\n") {
   108	            out.write_all(b"\n")?;
   109	        }
   110	    }
   111	}
