   166	impl ActiveSnapshot {
   167	    /// Merge with a `TransferComplete` to produce a
   168	    /// `TransferRecord`-shaped value that matches the JSON
   169	    /// schema emitted by `print_watch_json(Finished(...))`.
   170	    fn to_finished_complete(
   171	        &self,
   172	        c: &blit_core::generated::TransferComplete,
   173	    ) -> blit_core::generated::TransferRecord {
   174	        blit_core::generated::TransferRecord {
   175	            transfer_id: c.transfer_id.clone(),
   176	            kind: self.kind,
   177	            peer: self.peer.clone(),
   178	            module: self.module.clone(),
   179	            path: self.path.clone(),
   180	            start_unix_ms: self.start_unix_ms,
   181	            duration_ms: c.duration_ms,
   182	            bytes: c.bytes,
   183	            files: c.files,
