   190	    /// Merge with a `TransferError` to produce the same shape.
   191	    /// `duration_ms` derives from `start_unix_ms` since the
   192	    /// event itself doesn't carry it; partial bytes/files come from the
   193	    /// initial active snapshot.
   194	    fn to_finished_error(
   195	        &self,
   196	        e: &blit_core::generated::TransferError,
   197	    ) -> blit_core::generated::TransferRecord {
   198	        let now_ms = std::time::SystemTime::now()
   199	            .duration_since(std::time::UNIX_EPOCH)
   200	            .map(|d| d.as_millis() as u64)
   201	            .unwrap_or(0);
   202	        let duration_ms = now_ms.saturating_sub(self.start_unix_ms);
   203	        blit_core::generated::TransferRecord {
   204	            transfer_id: e.transfer_id.clone(),
   205	            kind: self.kind,
   206	            peer: self.peer.clone(),
   207	            module: self.module.clone(),
   208	            path: self.path.clone(),
   209	            start_unix_ms: self.start_unix_ms,
   210	            duration_ms,
   211	            bytes: self.bytes_completed,
   212	            files: self.files_completed,
   213	            tcp_fallback_used: false,
   214	            ok: false,
   215	            error_message: e.message.clone(),
   216	        }
   217	    }
   218	}
