   260	    }

  40	///   would double-count "M" on a local session, where both the source
  41	///   walk and the destination diff report on the one channel.
  42	/// - `SummaryReconciled { files_failed, bytes_landed }` is the SOURCE
  43	///   side's one correction (pfc-4). A send-side completion is not
  44	///   destination confirmation, and a send-side byte report is the
  45	///   PLANNED record size, so both lanes are optimistic about a file the
  46	///   destination could not write. When the destination's summary
  47	///   reports per-file failures the SOURCE retracts exactly that many of
  48	///   its own completions and adopts the summary's byte total. Emitted
  49	///   once, at the summary boundary, only by a producer whose reports
  50	///   were optimistic.
  51	/// - `DiffComplete` and `DeleteBegin` are PHASE signals (clp-2), not
  52	///   counters: they carry nothing, move no total, and a consumer that
  53	///   only tracks numbers ignores them. They exist because the counters
  54	///   alone cannot distinguish an up-to-date tree from a scan still
  55	///   running (both sit at zero needed files), nor a mirror's delete
  56	///   pass from the copy that preceded it.
  57	///
  58	/// [`ProgressTotals`] is the single shared fold for this contract;
  59	/// consumers must not re-derive per-direction folding rules.
  60	#[derive(Debug, Clone)]
  61	pub enum ProgressEvent {
  62	    /// Enumeration denominator: `files` more files and their declared
  63	    /// payload `bytes` are expected.
  64	    ManifestBatch { files: usize, bytes: u64 },
  65	    /// Source-walk liveness: the manifest scan has discovered `files`
  66	    /// more entries. Deliberately carries no bytes and no denominator
  67	    /// meaning — see the contract above.
  68	    Enumerated { files: u64 },
  69	    /// Transfer delta: `bytes` more bytes moved; `files` more files
  70	    /// finished on the aggregate lane (0 on per-file-lane producers).
  71	    Payload { files: usize, bytes: u64 },
  72	    /// Per-file lane: the file at the source-relative wire `path`
  73	    /// finished. Deliberately carries no byte count — bytes ride
  74	    /// [`ProgressEvent::Payload`] only.
  75	    FileComplete { path: String },
  76	    /// Per-file lane, DESTINATION side (JOB_LOGS jl-1b): the file at the
  77	    /// wire `path` did not land, and `reason` says why — so a job log can
  78	    /// name every failed file as it fails. Moves no count: the
  79	    /// destination's summary `files_failed` is authoritative.
  80	    FileFailed { path: String, reason: String },
  81	    /// DESTINATION side (JOB_LOGS jl-1b): the mirror-delete pass removed
  82	    /// the entry at the wire `path`; a directory's path ends in `/`. Moves
  83	    /// no count: the summary's `entries_deleted` is authoritative.
  84	    Deleted { path: String },
  85	    /// Phase signal (clp-2): the DESTINATION has diffed the whole
  86	    /// source manifest, so the `ManifestBatch` denominator is final.
  87	    /// Zero needed files after this means "up to date", not "still
  88	    /// scanning".
  89	    DiffComplete,
  90	    /// Phase signal (clp-2): the DESTINATION's mirror-delete pass has
  91	    /// started. The pass plans and deletes inside one blocking call, so
  92	    /// there is no per-entry lane to report against; without this a
  93	    /// consumer would still show the copy phase while extraneous
  94	    /// destination entries are being removed.
  95	    DeleteBegin,
  96	    /// Reconciliation (pfc-4, cr-pfc2-2): the destination's summary
  97	    /// reports that `files_failed` of the files this producer already
  98	    /// reported complete did not land, and that `bytes_landed` is the
  99	    /// byte total it actually wrote. A SOURCE-side producer completes a
 100	    /// file when it finishes SENDING it and reports that file's PLANNED
 101	    /// size, neither of which is destination confirmation; the
 102	    /// destination's `TransferSummary` is, and it arrives only at close.
 103	    /// The SOURCE emits this exactly once at that summary boundary so
 104	    /// its final counts are the ones that landed.
 105	    ///
 106	    /// `bytes_landed` REPLACES the running byte total instead of
 107	    /// subtracting from it: the wire carries no per-failure byte
 108	    /// attribution (the summary's `failures` list is a capped sample),
 109	    /// so the exact byte retraction is not derivable from the report —
 110	    /// only the authoritative total is.
 111	    ///
 112	    /// Destination-side producers never emit it — they already filter
 113	    /// completions and bytes against the write outcome, and a second
 114	    /// correction would subtract the same files twice.
 115	    SummaryReconciled {
 116	        files_failed: u64,
 117	        /// cr-ssc4-3: the destination's authoritative count of files that
 118	        /// landed. The fold ADOPTS it rather than subtracting
 119	        /// `files_failed` from the optimistic completions, because a
 120	        /// pre-announcement skip never emitted a completion to retract —
 121	        /// subtracting it would under-report every mixed run.
 122	        files_landed: u64,
 123	        bytes_landed: u64,
 124	    },
 125	}
