 127	/// Running totals folded from a [`ProgressEvent`] stream under the
 128	/// contract documented on the enum. This is the one shared
 129	/// accumulator (w6-1) — the CLI progress monitor and all three TUI
 130	/// transfer footers fold through it; per-direction folding rules no
 131	/// longer exist.
 132	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
 133	pub struct ProgressTotals {
 134	    /// Files announced by enumeration (`ManifestBatch`) — the
 135	    /// denominator, never part of transferred totals.
 136	    pub manifest_files: u64,
 137	    /// Bytes represented by the announced manifest entries. This is the
 138	    /// byte denominator paired with `manifest_files`; it never adds to the
 139	    /// transferred-byte count.
 140	    pub manifest_bytes: u64,
 141	    /// Entries the SOURCE walk has discovered (`Enumerated`). Liveness
 142	    /// only: never a denominator, never transferred work.
 143	    pub enumerated_files: u64,
 144	    /// Files finished, counted once each via either lane — net of any
 145	    /// `SummaryReconciled` retraction, so this is what LANDED.
 146	    pub files: u64,
 147	    /// Bytes transferred (`Payload` deltas, replaced once by
 148	    /// `SummaryReconciled`'s authoritative total when the destination
 149	    /// reports per-file failures) — so this too is what LANDED.
 150	    pub bytes: u64,
 151	    /// Files a `SummaryReconciled` retraction removed from `files`
 152	    /// (pfc-4): per-file failures the destination contained. Kept
 153	    /// separately so a consumer can say how many files did not land
 154	    /// without re-deriving it from the summary.
 155	    pub files_failed: u64,
 156	}
