 158	impl ProgressTotals {
 159	    /// Fold one event into the running totals.
 160	    pub fn apply(&mut self, event: &ProgressEvent) {
 161	        match event {
 162	            ProgressEvent::ManifestBatch { files, bytes } => {
 163	                self.manifest_files = self.manifest_files.saturating_add(*files as u64);
 164	                self.manifest_bytes = self.manifest_bytes.saturating_add(*bytes);
 165	            }
 166	            ProgressEvent::Enumerated { files } => {
 167	                self.enumerated_files = self.enumerated_files.saturating_add(*files);
 168	            }
 169	            ProgressEvent::Payload { files, bytes } => {
 170	                self.files = self.files.saturating_add(*files as u64);
 171	                self.bytes = self.bytes.saturating_add(*bytes);
 172	            }
 173	            ProgressEvent::FileComplete { .. } => {
 174	                self.files = self.files.saturating_add(1);
 175	            }
 176	            ProgressEvent::SummaryReconciled {
 177	                files_failed,
 178	                files_landed,
 179	                bytes_landed,
 180	            } => {
 181	                // cr-ssc4-3: adopt the destination's landed count. It is
 182	                // authoritative in both directions — the optimistic
 183	                // completions may be too high (a file the destination could
 184	                // not write) or too low (a skip announced no completion to
 185	                // retract).
 186	                self.files = *files_landed;
 187	                self.files_failed = self.files_failed.saturating_add(*files_failed);
 188	                // Not a delta — the destination's total is authoritative
 189	                // (see the variant's docs for why no delta exists).
 190	                self.bytes = *bytes_landed;
 191	            }
 192	            // Phase signals carry no counts by construction (clp-2).
 193	            ProgressEvent::DiffComplete | ProgressEvent::DeleteBegin => {}
 194	            // Names for a job log; the summary owns these counts.
 195	            ProgressEvent::FileFailed { .. } | ProgressEvent::Deleted { .. } => {}
 196	        }
 197	    }
 198	
 199	    /// True once any transfer work (not mere enumeration) has been
 200	    /// observed — the "show live totals" gate consumers share.
 201	    /// Reconciled-away work still counts: an all-failed session sent
 202	    /// and retracted real transfer work, and hiding its final transfer
 203	    /// event would misreport the run as enumeration-only (cr-pfc4-3).
 204	    pub fn started(&self) -> bool {
 205	        self.files > 0 || self.bytes > 0 || self.files_failed > 0
 206	    }
 207	}
